import csv
import json
import os
import sys
import time

from pyscipopt import Model, quicksum

BASE = "/app"
DATA = os.path.join(BASE, "data")
SUB = os.path.join(BASE, "submissions")
os.makedirs(SUB, exist_ok=True)

TOL = 1e-5


def read_csv(path):
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def main():
    # Read data
    with open(os.path.join(DATA, "config.json")) as f:
        config = json.load(f)
    tol = float(config.get("feasibility_tolerance", 1e-5))

    days_rows = read_csv(os.path.join(DATA, "days.csv"))
    rooms_rows = read_csv(os.path.join(DATA, "rooms.csv"))
    lots_rows = read_csv(os.path.join(DATA, "crop_lots.csv"))
    options_rows = read_csv(os.path.join(DATA, "harvest_options.csv"))
    demand_rows = read_csv(os.path.join(DATA, "crop_day_demand.csv"))

    days = [r["day"] for r in days_rows]
    day_idx = {r["day"]: int(r["day_index"]) for r in days_rows}
    energy_price = {r["day"]: float(r["energy_price_per_kwh"]) for r in days_rows}
    led_limit = {r["day"]: float(r["led_energy_limit_kwh"]) for r in days_rows}
    labor_limit = {r["day"]: float(r["harvest_labor_hours"]) for r in days_rows}
    cooler_limit = {r["day"]: float(r["cooler_capacity_kg"]) for r in days_rows}

    room_cap = {r["room_id"]: float(r["max_trays_harvested_per_day"]) for r in rooms_rows}

    lots = {}
    for r in lots_rows:
        lots[r["lot_id"]] = {
            "crop": r["crop"],
            "room": r["room_id"],
            "trays": float(r["trays_available"]),
        }

    options = {}
    for r in options_rows:
        lid = r["lot_id"]
        d = r["day"]
        options[(lid, d)] = {
            "yield": float(r["yield_kg_per_tray"]),
            "energy": float(r["energy_kwh_per_tray"]),
            "labor": float(r["labor_hours_per_tray"]),
            "quality": float(r["quality_penalty_per_tray"]),
        }

    demand = {}
    service = {}
    shortage_pen = {}
    crops = set()
    for r in demand_rows:
        c = r["crop"]
        d = r["day"]
        crops.add(c)
        demand[(c, d)] = float(r["demand_kg"])
        service[(c, d)] = float(r["minimum_service_rate"])
        shortage_pen[(c, d)] = float(r["shortage_penalty_per_kg"])

    # Build model
    model = Model("vertical_farm_harvest")
    model.setMinimize()
    model.setRealParam("limits/gap", 0.0005)

    time_limit_env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if time_limit_env:
        tl = float(time_limit_env)
    else:
        tl = 300.0
    model.setRealParam("limits/time", tl)

    # Decision variables
    x = {}
    for (lid, d), opt in options.items():
        # Objective: energy cost + quality penalty
        obj = energy_price[d] * opt["energy"] + opt["quality"]
        var = model.addVar(
            name=f"x_{lid}_{d}",
            vtype="C",
            lb=0.0,
            ub=lots[lid]["trays"],
            obj=obj,
        )
        x[(lid, d)] = var

    s = {}
    for c in sorted(crops):
        for d in days:
            max_short = (1.0 - service[(c, d)]) * demand[(c, d)]
            var = model.addVar(
                name=f"s_{c}_{d}",
                vtype="C",
                lb=0.0,
                ub=max(0.0, max_short),
                obj=shortage_pen[(c, d)],
            )
            s[(c, d)] = var

    # Constraints
    # 1. Lot availability
    for lid in lots:
        lot_days = [d for (l, d) in options if l == lid]
        if lot_days:
            model.addCons(
                quicksum(x[(lid, d)] for d in lot_days) <= lots[lid]["trays"],
                name=f"lot_{lid}",
            )

    # 2. Room/day capacity
    for r_id, cap in room_cap.items():
        for d in days:
            room_lots = [lid for lid in lots if lots[lid]["room"] == r_id]
            terms = []
            for lid in room_lots:
                if (lid, d) in x:
                    terms.append(x[(lid, d)])
            if terms:
                model.addCons(quicksum(terms) <= cap, name=f"room_{r_id}_{d}")

    # 3. Daily LED energy
    for d in days:
        terms = []
        for (lid, dd), opt in options.items():
            if dd == d:
                terms.append(opt["energy"] * x[(lid, d)])
        if terms:
            model.addCons(quicksum(terms) <= led_limit[d], name=f"energy_{d}")

    # 4. Daily labor
    for d in days:
        terms = []
        for (lid, dd), opt in options.items():
            if dd == d:
                terms.append(opt["labor"] * x[(lid, d)])
        if terms:
            model.addCons(quicksum(terms) <= labor_limit[d], name=f"labor_{d}")

    # 5. Daily cooler
    for d in days:
        terms = []
        for (lid, dd), opt in options.items():
            if dd == d:
                terms.append(opt["yield"] * x[(lid, d)])
        if terms:
            model.addCons(quicksum(terms) <= cooler_limit[d], name=f"cooler_{d}")

    # 6. Demand balance
    for c in sorted(crops):
        for d in days:
            terms = []
            for lid in lots:
                if lots[lid]["crop"] == c and (lid, d) in x:
                    terms.append(options[(lid, d)]["yield"] * x[(lid, d)])
            model.addCons(
                quicksum(terms) + s[(c, d)] == demand[(c, d)],
                name=f"demand_{c}_{d}",
            )

    # Solve
    t0 = time.time()
    model.optimize()
    solve_time = time.time() - t0

    status = model.getStatus()
    objval = model.getObjVal()

    print(f"Status: {status}")
    print(f"Objective: {objval:.8f}")
    print(f"Solve time: {solve_time:.2f}s")

    # Extract solution
    harvest_rows = []
    for (lid, d), var in x.items():
        val = model.getVal(var)
        if val > tol:
            crop = lots[lid]["crop"]
            harvest_rows.append(("harvest", lid, crop, d, val))

    shortage_rows = []
    for c in sorted(crops):
        for d in days:
            var = s[(c, d)]
            val = model.getVal(var)
            if val > tol:
                shortage_rows.append(("shortage", "", c, d, val))

    # Write solution
    out_path = os.path.join(SUB, "solution.csv")
    with open(out_path, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["row_type", "lot_id", "crop", "day", "value"])
        for row in harvest_rows:
            writer.writerow([row[0], row[1], row[2], row[3], f"{row[4]:.8f}"])
        for row in shortage_rows:
            writer.writerow([row[0], row[1], row[2], row[3], f"{row[4]:.8f}"])

    print(f"Solution written to {out_path}")
    print(f"Harvest rows: {len(harvest_rows)}, Shortage rows: {len(shortage_rows)}")

    # Validation
    print("\n--- Validation ---")
    # Check lot availability
    lot_harvest = {lid: 0.0 for lid in lots}
    for (lid, d), var in x.items():
        lot_harvest[lid] += model.getVal(var)
    for lid, total in lot_harvest.items():
        if total > lots[lid]["trays"] + tol:
            print(f"VIOLATION: lot {lid} harvested {total} > {lots[lid]['trays']}")

    # Check room capacity
    for r_id, cap in room_cap.items():
        for d in days:
            total = 0.0
            for lid in lots:
                if lots[lid]["room"] == r_id and (lid, d) in x:
                    total += model.getVal(x[(lid, d)])
            if total > cap + tol:
                print(f"VIOLATION: room {r_id} day {d}: {total} > {cap}")

    # Check daily resources
    for d in days:
        energy = sum(options[(lid, d)]["energy"] * model.getVal(x[(lid, d)]) for (lid, dd) in x if dd == d)
        labor = sum(options[(lid, d)]["labor"] * model.getVal(x[(lid, d)]) for (lid, dd) in x if dd == d)
        cooler = sum(options[(lid, d)]["yield"] * model.getVal(x[(lid, d)]) for (lid, dd) in x if dd == d)
        if energy > led_limit[d] + tol:
            print(f"VIOLATION: energy day {d}: {energy} > {led_limit[d]}")
        if labor > labor_limit[d] + tol:
            print(f"VIOLATION: labor day {d}: {labor} > {labor_limit[d]}")
        if cooler > cooler_limit[d] + tol:
            print(f"VIOLATION: cooler day {d}: {cooler} > {cooler_limit[d]}")

    # Check demand balance
    for c in sorted(crops):
        for d in days:
            harvested_kg = sum(
                options[(lid, d)]["yield"] * model.getVal(x[(lid, d)])
                for lid in lots
                if lots[lid]["crop"] == c and (lid, d) in x
            )
            short = model.getVal(s[(c, d)])
            total = harvested_kg + short
            if abs(total - demand[(c, d)]) > tol:
                print(f"VIOLATION: demand {c} {d}: {total} != {demand[(c, d)]}")
            max_short = (1.0 - service[(c, d)]) * demand[(c, d)]
            if short > max_short + tol:
                print(f"VIOLATION: shortage {c} {d}: {short} > {max_short}")

    print("Validation complete.")


if __name__ == "__main__":
    main()
